import http from 'k6/http'; import {check, sleep} from 'k6'; import {baseURL,thresholds} from '../lib/config.js'; import {checkJSON,tags} from '../lib/checks.js';
const soak=__ENV.SOAK_DURATION||'10m'; export const options={scenarios:{health:{executor:'ramping-vus',stages:[{duration:'30s',target:4},{duration:soak,target:8},{duration:'30s',target:0}],exec:'health'},errors:{executor:'constant-arrival-rate',rate:2,timeUnit:'1s',duration:soak,preAllocatedVUs:2,exec:'errors'},state:{executor:'ramping-arrival-rate',startRate:1,timeUnit:'1s',preAllocatedVUs:2,stages:[{duration:'30s',target:2},{duration:soak,target:5},{duration:'30s',target:0}],exec:'state'}},thresholds:thresholds('load',['secret_leaks','schema_success','route_success','route_duration'])};
export function setup(){const r=http.get(`${baseURL()}/__test/metrics`);checkJSON(r,200,v=>v.goroutines>0&&v.heap_alloc>0);return r.json()}
export function health(){checkJSON(http.get(`${baseURL()}/health`,{tags:{...tags('stability','health',200),name:'GET /health'}}),200,v=>v&&typeof v==='object');sleep(0.05)}
export function errors(){checkJSON(http.get(`${baseURL()}/__missing__`,{tags:tags('stability','missing',404)}),404,v=>v&&v.error&&v.error.code==='not_found'&&typeof v.error.message==='string')}
export function state(){checkJSON(http.get(`${baseURL()}/__test/metrics`,{tags:tags('stability','metrics',200)}),200,v=>v&&typeof v==='object')}
export function teardown(base){const maxG=Number(__ENV.MAX_GOROUTINE_GROWTH||50),maxH=Number(__ENV.MAX_HEAP_GROWTH||67108864),r=http.get(`${baseURL()}/__test/metrics`),v=r.json();check(r,{'stability final metrics status 200':x=>x.status===200,'stability final active requests zero':()=>v.active_requests<=1,'stability final SSE connections zero':()=>v.sse_connections===0,'stability final WS connections zero':()=>v.ws_connections===0,'stability goroutine growth bounded':()=>v.goroutines-base.goroutines<=maxG,'stability heap growth bounded':()=>v.heap_alloc-base.heap_alloc<=maxH,'stability total requests increased':()=>v.total_requests>=base.total_requests,'stability GC count monotonic':()=>v.num_gc>=base.num_gc});}
export default health;

